// Access to Chummer5a reference data (skills, metatypes, items) for the .chum5 import/export.
// Primary source: the Chummer data folder (../Chummer5.226.0/data, or env CHUMMER_DATA_DIR), parsed lazily.
// Fallbacks when it is absent: snapshot.json (skills, metatypes, grades — generated by build-snapshot.js)
// and the app catalog (data/catalog/*.json, whose ids ARE Chummer GUIDs) for item names/stats.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseXml } from './xml.js';

const HERE = path.dirname(fileURLToPath(import.meta.url));
export const APP_ROOT = path.resolve(HERE, '..', '..', '..');
const CATALOG_DIR = path.join(APP_ROOT, 'data', 'catalog');

export function chummerDataDir() {
  return process.env.CHUMMER_DATA_DIR ? path.resolve(process.env.CHUMMER_DATA_DIR) : path.resolve(APP_ROOT, '..', 'Chummer5.226.0', 'data');
}

const docCache = new Map();
/** Root element of a Chummer data file (e.g. 'weapons.xml'), or null when unavailable. */
export function dataRoot(file) {
  if (docCache.has(file)) return docCache.get(file);
  let root = null;
  try {
    root = parseXml(fs.readFileSync(path.join(chummerDataDir(), file), 'utf8')).root;
  } catch {
    root = null;
  }
  docCache.set(file, root);
  return root;
}

let snapshotCache;
export function snapshot() {
  if (snapshotCache === undefined) {
    try {
      snapshotCache = JSON.parse(fs.readFileSync(path.join(HERE, 'snapshot.json'), 'utf8'));
    } catch {
      snapshotCache = null;
    }
  }
  return snapshotCache;
}

export const norm = (s) =>
  String(s ?? '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[’`]/g, "'")
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();

/** norm() without punctuation: "Yeux cybernétiques (système de base)" ≈ "Yeux cybernétiques, système de base". */
export const loose = (s) => norm(s).replace(/[^a-z0-9]+/g, ' ').trim();

// ---------------------------------------------------------------------------
// Skills
// ---------------------------------------------------------------------------
let skillsCache = null;
/** { active: [{ id, name, attr, category, group, default, exotic }], groups: [name], knowledge: [{ id, name, attr, category }] } */
export function skillsData() {
  if (skillsCache) return skillsCache;
  const root = dataRoot('skills.xml');
  if (root) {
    const active = (root.child('skills')?.all('skill') || []).map((s) => ({
      id: s.val('id').toLowerCase(), name: s.val('name'), attr: s.val('attribute'), category: s.val('category'), group: s.val('skillgroup'),
      default: s.val('default') === 'True', exotic: s.val('exotic') === 'True', source: s.val('source'),
    }));
    const groups = (root.child('skillgroups')?.all('name') || []).map((g) => g.text);
    const knowledge = (root.child('knowledgeskills')?.all('skill') || []).map((s) => ({ id: s.val('id').toLowerCase(), name: s.val('name'), attr: s.val('attribute'), category: s.val('category') }));
    skillsCache = { active, groups, knowledge };
  } else {
    const snap = snapshot();
    skillsCache = snap?.skills || { active: [], groups: [], knowledge: [] };
  }
  skillsCache.byId = new Map(skillsCache.active.map((s) => [s.id, s]));
  skillsCache.byName = new Map(skillsCache.active.map((s) => [norm(s.name), s]));
  skillsCache.knoByName = new Map(skillsCache.knowledge.map((s) => [norm(s.name), s]));
  return skillsCache;
}

/** App skill id (shared/sr5.js) from a Chummer skill name. */
export function appSkillId(chummerName) {
  const n = String(chummerName || '');
  if (/^Exotic (Melee|Ranged) Weapon/i.test(n)) return 'exotic_weapon';
  return (
    n
      .normalize('NFD')
      .replace(/[̀-ͯ]/g, '')
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '_')
      .replace(/^_|_$/g, '') || 'x'
  );
}

/** Chummer skill definition for an app skill id (or a Chummer/English name). */
export function chummerSkillFor(appId, name) {
  const sd = skillsData();
  if (appId === 'exotic_weapon') return sd.byName.get('exotic ranged weapon') || null;
  for (const s of sd.active) if (appSkillId(s.name) === appId) return s;
  if (name) return sd.byName.get(norm(name)) || null;
  return null;
}

// ---------------------------------------------------------------------------
// Metatypes
// ---------------------------------------------------------------------------
export const METATYPE_EN = { Humain: 'Human', Elfe: 'Elf', Nain: 'Dwarf', Ork: 'Ork', Troll: 'Troll' };
export const METATYPE_FROM_EN = { Human: 'Humain', Elf: 'Elfe', Dwarf: 'Nain', Ork: 'Ork', Troll: 'Troll' };
const ATTR_KEYS = { BOD: 'bod', AGI: 'agi', REA: 'rea', STR: 'str', CHA: 'cha', INT: 'int', LOG: 'log', WIL: 'wil', EDG: 'edg', MAG: 'mag', RES: 'res', ESS: 'ess', DEP: 'dep', INI: 'ini' };

const metaCache = new Map();
/** { id, name, category, karma, walk, run, sprint, attrs: { BOD: { min, max, aug }, … } } or null. */
export function metatypeData(nameEn) {
  const key = norm(nameEn || 'Human');
  if (metaCache.has(key)) return metaCache.get(key);
  let out = null;
  const root = dataRoot('metatypes.xml');
  if (root) {
    const m = (root.child('metatypes')?.all('metatype') || []).find((x) => norm(x.val('name')) === key);
    if (m) {
      const attrs = {};
      for (const [k, p] of Object.entries(ATTR_KEYS)) {
        attrs[k] = { min: Number(m.val(`${p}min`)) || 0, max: Number(m.val(`${p}max`)) || 0, aug: Number(m.val(`${p}aug`)) || 0 };
      }
      out = { id: m.val('id').toLowerCase(), name: m.val('name'), category: m.val('category'), karma: Number(m.val('karma')) || 0, walk: m.val('walk'), run: m.val('run'), sprint: m.val('sprint'), attrs };
    }
  }
  if (!out) out = snapshot()?.metatypes?.find((x) => norm(x.name) === key) || null;
  metaCache.set(key, out);
  return out;
}

// ---------------------------------------------------------------------------
// Items (data XML nodes + app catalog)
// ---------------------------------------------------------------------------
/** kind → [file, container, node] */
export const DATA_FILES = {
  weapons: ['weapons.xml', 'weapons', 'weapon'],
  armor: ['armor.xml', 'armors', 'armor'],
  gear: ['gear.xml', 'gears', 'gear'],
  cyberware: ['cyberware.xml', 'cyberwares', 'cyberware'],
  bioware: ['bioware.xml', 'biowares', 'bioware'],
  qualities: ['qualities.xml', 'qualities', 'quality'],
  powers: ['powers.xml', 'powers', 'power'],
  spells: ['spells.xml', 'spells', 'spell'],
  lifestyles: ['lifestyles.xml', 'lifestyles', 'lifestyle'],
  vehicles: ['vehicles.xml', 'vehicles', 'vehicle'],
  complexforms: ['complexforms.xml', 'complexforms', 'complexform'],
};

const indexCache = new Map();
function dataIndex(kind) {
  if (indexCache.has(kind)) return indexCache.get(kind);
  const spec = DATA_FILES[kind];
  const idx = { byId: new Map(), byName: new Map() };
  const root = spec && dataRoot(spec[0]);
  for (const n of root?.child(spec[1])?.all(spec[2]) || []) {
    const id = n.val('id').toLowerCase();
    if (id) idx.byId.set(id, n);
    const nm = norm(n.val('name'));
    if (nm && !idx.byName.has(nm)) idx.byName.set(nm, n);
  }
  indexCache.set(kind, idx);
  return idx;
}

/** Chummer data node for an item: by GUID, else by (English) name. */
export function findDataItem(kind, { id, name } = {}) {
  const idx = dataIndex(kind);
  if (id) {
    const n = idx.byId.get(String(id).toLowerCase());
    if (n) return n;
  }
  if (name) return idx.byName.get(norm(name)) || null;
  return null;
}

/** Cyberware/bioware grade names → { ess multiplier } from the data file (fallback: SR5 core values). */
export function gradeTable(kind = 'cyberware') {
  const root = dataRoot(kind === 'bioware' ? 'bioware.xml' : 'cyberware.xml');
  const out = {};
  for (const g of root?.child('grades')?.all('grade') || []) out[g.val('name')] = { id: g.val('id'), ess: Number(g.val('ess')) || 1 };
  if (!Object.keys(out).length) Object.assign(out, snapshot()?.grades || {});
  return out;
}

// App catalog (data/catalog/<name>.json)
const catCache = new Map();
export function appCatalog(name) {
  if (catCache.has(name)) return catCache.get(name);
  let list = [];
  try {
    const raw = JSON.parse(fs.readFileSync(path.join(CATALOG_DIR, `${name}.json`), 'utf8'));
    list = Array.isArray(raw) ? raw : raw.items || [];
  } catch {
    list = [];
  }
  const byId = new Map(list.map((e) => [String(e.id).toLowerCase(), e]));
  const byName = new Map();
  const byLoose = new Map();
  const byStem = new Map();
  const put = (m, k, e) => k && !m.has(k) && m.set(k, e);
  for (const e of list) {
    for (const nm of [e.name, e.nameFr]) {
      put(byName, norm(nm), e);
      put(byLoose, loose(nm), e);
      put(byStem, loose(String(nm || '').replace(/\s*\([^)]*\)\s*$/, '')), e);
    }
  }
  const out = { list, byId, byName, byLoose, byStem };
  catCache.set(name, out);
  return out;
}

/** Catalog file names that can hold a given Chummer data kind. */
export const KIND_CATALOGS = {
  weapons: ['weapons'], armor: ['armor'], gear: ['gear', 'programs'], cyberware: ['cyberware'], bioware: ['bioware'],
  qualities: ['qualities'], powers: ['powers'], spells: ['spells'], lifestyles: ['lifestyles'], vehicles: ['vehicles'], complexforms: [],
};

/** App catalog entry by GUID or by English/French name. */
export function findCatalogEntry(kind, { id, name } = {}) {
  for (const c of KIND_CATALOGS[kind] || []) {
    const cat = appCatalog(c);
    if (id) {
      const e = cat.byId.get(String(id).toLowerCase());
      if (e) return e;
    }
  }
  if (name) {
    for (const map of ['byName', 'byLoose', 'byStem']) {
      for (const c of KIND_CATALOGS[kind] || []) {
        const e = appCatalog(c)[map].get(map === 'byName' ? norm(name) : loose(name));
        if (e) return e;
      }
    }
  }
  return null;
}

/** French display name for a Chummer GUID (app catalog), or null. */
export function frenchName(kind, id) {
  const e = id ? findCatalogEntry(kind, { id }) : null;
  return e?.nameFr || null;
}

/** French category for a Chummer GUID (app catalog), or null. */
export function frenchCategory(kind, id) {
  const e = id ? findCatalogEntry(kind, { id }) : null;
  return e?.categoryFr || null;
}
